import socket
# Scan 172.28.1.0/24 and 172.28.2.0/24 and 172.29.0.0/24 quickly for 8081
import concurrent.futures

def scan(ip):
    s = socket.socket()
    s.settimeout(0.1)
    try:
        s.connect((ip, 8081))
        return ip, True
    except Exception:
        return ip, False
    finally:
        s.close()

for net in ['172.28.1', '172.28.2', '172.28.3', '172.29.0']:
    found = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=200) as ex:
        futs = {ex.submit(scan, f'{net}.{i}'): i for i in range(1, 255)}
        for f in concurrent.futures.as_completed(futs):
            ip, ok = f.result()
            if ok:
                found.append(ip)
    print(net, 'found:', found)
EOF"}

