        return data
    except Exception:
        return None

def parse_answers(data):
    if not data: return []
    ancount = data[6]*256+data[7]
    i = 12
    if i >= len(data): return []
    while i < len(data) and data[i] != 0:
        if data[i] & 0xc0 == 0xc0:
            i += 2
            break
        i += data[i]+1
    if i < len(data): i += 1
    i += 4
    out = []
    for _ in range(ancount):
        if i+2 > len(data): break
        if data[i] & 0xc0 == 0xc0:
            i += 2
        if i+10 > len(data): break
        rtype, rclass, ttl, rdlen = struct.unpack('>HHIH', data[i:i+10])
        i += 10
        if i+rdlen > len(data): break
        rdata = data[i:i+rdlen]
        if rtype == 1 and rdlen == 4:
            out.append(('A', '.'.join(str(x) for x in rdata)))
        elif rtype == 5:
