                if rdata[j] & 0xc0 == 0xc0:
                    ptr = struct.unpack('>H', rdata[j:j+2])[0] & 0x3fff
                    k = ptr
                    while k < len(data) and data[k] != 0:
                        l = data[k]; k += 1
                        if k+l <= len(data):
                            lbl.append(data[k:k+l].decode()); k += l
                    j += 2
                    break
                else:
                    l = rdata[j]; j += 1
                    if j+l <= len(rdata):
