        elif rtype == 16:
            j = 0
            vals = []
            while j < len(rdata):
                l = rdata[j]; j += 1
                vals.append(rdata[j:j+l].decode(errors='replace')); j += l
            out.append(('TXT', ';'.join(vals)))
        i += rdlen
    return out

